mapper.select:
select count(1) from sys_vegetable_category
where parent_id = #{parentId} and category_name = #{name}
and category_id != #{excludeId}

mapper.update:
update sys_vegetable_category set parent_id = #{parentId}, ancestors = #{ancestors}, category_name = #{categoryName},
order_num = #{orderNum}, status = #{status}, update_by = #{updateBy}, update_time = now()
where category_id = #{categoryId}

update sys_vegetable_record set category_id = #{categoryId}, user_id = #{userId},
planting_days = #{plantingDays}, issue = #{issue}, update_by = #{updateBy}, update_time = now()
where record_id = #{recordId}
